SELECT COUNT(*) AS n_pairs, SUM(f.generated_at > o.generated_at) AS five_after_one, SUM(f.generated_at <= o.generated_at) AS five_at_or_before_one, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, o.generated_at, f.generated_at))/1000,1) AS avg_ms, ROUND(MAX(TIMESTAMPDIFF(MICROSECOND, o.generated_at, f.generated_at))/1000,1) AS max_ms FROM trade_signal f JOIN trade_signal o ON o.symbol = f.symbol AND o.interval_code = '1m' AND o.candle_open_time = f.candle_open_time + INTERVAL 4 MINUTE WHERE f.interval_code = '5m' AND f.candle_open_time >= '2026-10-11 00:00:00' AND f.candle_open_time < '2026-10-12 18:00:00'